import datetime
from builtins import str, object
from time import sleep
from taf.ul.trs_e2e_fw.lib.remote_connection.remoteconnection import RemoteConnection
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger


logger = BackgroundLogger.Instance()


class DatetimeOperations(object):
    """
    DatetimeOperations
    """
    def extract_mtime(self, pm_file):
        """
        Function to extract mtime
        """
        month_dict = {'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04', 'may': '05', 'jun': '06',
                      'jul': '07', 'aug': '08', 'sep': '09', 'oct': '10', 'nov': '11', 'dec': '12'}
        fields = pm_file.split(' ')
        YYYY = int(fields[-2])
        hhmmss = fields[-3].split(':')
        hh = int(hhmmss[0])
        mm = int(hhmmss[1])
        # ss = int(hhmmss[2])
        dd = int(fields[-4])
        MM = int(month_dict[fields[-6].lower()])
        return datetime.datetime(YYYY, MM, dd, hh, mm, 0)

    def format_time_stamp_from_xml_or_json(self, time_unformatted):
        """
        Function to format time stamp from xml or json
        """
        split_values = time_unformatted.split('T')
        ymd = split_values[0].split('-')
        hms = split_values[1].split('.')[0].split(':')
        YYYY = int(ymd[0])
        MM = int(ymd[1])
        dd = int(ymd[2])
        hh = int(hms[0])
        mm = int(hms[1])
        # ss = int(hhmmss[2])
        return datetime.datetime(YYYY, MM, dd, hh, mm, 0).strftime('%Y%m%d%H%M')

    def generate_expected_starttimes_using_mtime(self, pm_file_name, mtime):
        """
        Function to generate expected starttimes using mtime
        """
        if 'raw' in pm_file_name:
            interval = mtime - datetime.timedelta(minutes=16)
            return [interval.strftime('%Y%m%d%H%M')]
        elif 'xml' in pm_file_name:
            expected_timestamps = []
            for delta in [76, 61, 46, 31]:
                interval = mtime - datetime.timedelta(minutes=delta)
                timestamp = interval.strftime('%Y%m%d%H%M')
                expected_timestamps.append(timestamp)
            return expected_timestamps

    def convert_string_to_datetime(self, timestamp_str):
        """
        Function to convert string to datetime
        """
        date_obj = datetime.datetime.strptime(timestamp_str, '%Y%m%d%H%M')
        return date_obj

    def format_timestamps(self, timestamps_in_file):
        """
        Function to format timestamps
        """
        formatted_timestamps = []
        for time_stamp in timestamps_in_file:
            formatted_timestamps.append(self.format_time_stamp_from_xml_or_json(time_stamp))
        return formatted_timestamps

    # def wait_for_next_interval(self, current_time, interval, dut, additional_wait_time):
    def wait_for_next_interval(self, current_time, interval, additional_wait_time):
        """
        Function to wait for next interval
        """
        # current_time = datetime.datetime.now()
        # current_time = self.get_currenttime_on_enb(dut)
        if interval == '15':
            return self._wait_for_next_15_min_interval(current_time, additional_wait_time)
        elif interval == '30':
            return self._wait_for_next_30_min_interval(current_time, additional_wait_time)
        elif interval == '60':
            return self._wait_for_next_60_min_interval(current_time, additional_wait_time)
        elif interval == '5':
            return self._wait_for_next_5_min_interval(current_time, additional_wait_time)
        # self.get_currenttime_on_enb(dut)

    def get_current_interval_start_time(self, interval, current_time, additional_wait_time):
        """
        Get current interval start time
        @param interval: int, interval
        @param current_time: datetime, current time
        @param additional_wait_time: int, additional wait time
        @return interval start time
        """
        # current_time = current_time if current_time is not None else self.get_currenttime_on_enb(dut)
        interval = int(interval)
        minutes_past_last_interval = current_time.minute % int(interval)
        if minutes_past_last_interval == 0:                                 ## Eg: 11:30, 11:45 etc..
            minutes_past_last_interval_delta = datetime.timedelta(minutes=interval)

        else:
            minutes_past_last_interval_delta = datetime.timedelta(minutes=minutes_past_last_interval)
            # interval_start_min = current_time.minute - minutes_past_last_interval
        interval_start_time = current_time - minutes_past_last_interval_delta
        # interval_start_time = current_time.replace(minute=interval_start_min, second=0)
        interval_start_time = interval_start_time + datetime.timedelta(seconds=additional_wait_time)
        return interval_start_time

    def _wait_for_next_15_min_interval(self, current_time, additional_wait_time):
        minutes_past_last_interval = current_time.minute % 15
        if minutes_past_last_interval > 0:
            seconds_past_last_interval = minutes_past_last_interval * 60 + current_time.second
            # wait_seconds = (15 * 60) - seconds_past_last_interval
            # logger.debug("Wait time for Interval Closure: {0}".format(str(
            # datetime.timedelta(seconds=wait_seconds))))
            wait_seconds = (15 * 60) - seconds_past_last_interval + additional_wait_time
            if wait_seconds < 0:
                wait_seconds = -wait_seconds
            logger.debug("additional_wait_time: {}".format(additional_wait_time))
            wait_time_delta = datetime.timedelta(seconds=wait_seconds)
            logger.debug("Wait time for Interval Closure: {0} ".format(str(wait_time_delta)))
            sleep(wait_seconds)
            return current_time + wait_time_delta
        return current_time

    def _wait_for_next_60_min_interval(self, current_time, additional_wait_time):
        minutes_past_last_interval = current_time.minute
        current_sec = current_time.second
        if minutes_past_last_interval > 0:
            wait_seconds = (60 - minutes_past_last_interval) * 60 + (60 - current_sec) + additional_wait_time
            if wait_seconds < 0:
                wait_seconds = -wait_seconds
            sleep(wait_seconds)

    def _wait_for_next_30_min_interval(self, current_time, additional_wait_time):
        current_min = current_time.minute
        current_sec = current_time.second
        logger.debug(current_time)
        if current_min != 0 and current_min < 30:
            wait_seconds = (30 - current_min) * 60 + (60 - current_sec) + additional_wait_time
            if wait_seconds < 0:
                wait_seconds = -wait_seconds
            sleep(wait_seconds)
        elif current_min > 30:
            self._wait_for_next_60_min_interval(current_time, additional_wait_time)

    def _wait_for_next_5_min_interval(self, current_time, additional_wait_time):
        minutes_past_last_interval = current_time.minute % 5
        if minutes_past_last_interval > 0:
            seconds_past_last_interval = minutes_past_last_interval * 60 + current_time.second
            wait_seconds = (5 * 60) - seconds_past_last_interval + additional_wait_time
            if wait_seconds < 0:
                wait_seconds = -wait_seconds
            logger.debug("additional_wait_time: {}".format(additional_wait_time))
            wait_time_delta = datetime.timedelta(seconds=wait_seconds)
            logger.debug("Wait time for Interval Closure: {0} ".format(str(wait_time_delta)))
            sleep(wait_seconds)
            return current_time + wait_time_delta
        return current_time

    def get_currenttime_on_enb(self, dut, format='%Y-%m-%d %H:%M:%S', time_zone='dut'):
        """Get current time on Enb
        @param dut: dut
        @param format: Date format
        @param time_zone: time zone
        @return current time on enb
        """
        logger.debug("Getting current time on enb ...")
        remote_obj = RemoteConnection()
        remote_obj.setup_remote_access(remote_device=dut)
        if time_zone.lower() == 'utc':
            time_zone = '-u'
        else:
            time_zone = ''
        datetime_string = remote_obj.remote_command_execute(command="date {} '+%Y-%m-%d %H:%M:%S'".format(
            time_zone)).replace('\n', '')
        logger.debug("Current Time on enb is {}".format(datetime_string))
        remote_obj.teardown_remote_access()
        return datetime.datetime.strptime(datetime_string, format)

    def get_datetime_from_filename(self, pm_file):
        """
        Returns date time object prepared from the extracted timestamp string
        :param pm_file
        :return:
        """
        # Filename sample 'PM.BTS-3245.20170531.080000.LTE.xml.xml'
        filename_fields = pm_file.split('.')
        date_field = filename_fields[2]
        time_field = filename_fields[3]
        return datetime.datetime.strptime('{}{}'.format(date_field, time_field), '%Y%m%d%H%M%S')

    def get_oldest_datetime(self):
        """
        Function to get oldest datetime
        """
        return datetime.datetime.min
